EXPORT ZZT_STULIST() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1,3},{1}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1},{1,3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(1,4),3},{1}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(1,4)},{1,3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1,3},{(1,4)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1},{(1,4),3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({},{1}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1},{}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;

EXPORT ZZT_STULIST() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
L1:={(1,4),3}; L2:={1};
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(1+1,-4),2+1},{1+0}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev(L1,L2); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev(L2,L1); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)},{ZZT_TICK(4,1)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({ZZT_TICK(1,1)},{ZZT_TICK(2,1),ZZT_TICK(3,3)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(ZZT_FAIL(1),ZZT_TICK(2,4)),ZZT_TICK(3,3)},{ZZT_TICK(4,1)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({ZZT_TICK(1,1)},{ZZT_TICK(2,1),ZZT_FAIL(3)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_STULIST() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1,3},{1,3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(1,4),3},{1,3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({(1,4),3},{-1,1}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
